"""Cross-source deduplication service for RegionEvent records."""

from __future__ import annotations

import re
from datetime import datetime, timedelta
from difflib import SequenceMatcher
from typing import TYPE_CHECKING, Any

if TYPE_CHECKING:
    from trips.models import RegionCalendar, RegionEvent

# Minimum SequenceMatcher ratio to consider two names a match.
NAME_SIMILARITY_THRESHOLD = 0.75
SAME_SOURCE_NAME_SIMILARITY_THRESHOLD = 0.82
SAME_SOURCE_STRONG_NAME_SIMILARITY_THRESHOLD = 0.93
DESCRIPTION_SIMILARITY_THRESHOLD = 0.55
STRONG_DESCRIPTION_SIMILARITY_THRESHOLD = 0.9
LOCATION_SIMILARITY_THRESHOLD = 0.8

# Maximum number of days apart for start dates to be considered the same event.
DATE_WINDOW_DAYS = 1


def normalize_name(name: str) -> str:
    """Lowercase, strip non-alphanumeric (except spaces), collapse whitespace."""
    name = name.lower()
    name = re.sub(r"[^a-z0-9 ]", "", name)
    return re.sub(r"\s+", " ", name).strip()


def names_match(a: str, b: str) -> float:
    """Return SequenceMatcher ratio on normalized names."""
    return SequenceMatcher(None, normalize_name(a), normalize_name(b)).ratio()


def text_similarity(a: str, b: str) -> float:
    """Return SequenceMatcher ratio on normalized free text."""
    return SequenceMatcher(None, normalize_name(a), normalize_name(b)).ratio()


class RegionEventDedupService:
    """Detect and resolve cross-source duplicate RegionEvent records."""

    @staticmethod
    def find_cross_source_duplicate(
        region_calendar: RegionCalendar,
        name: str,
        start_datetime: datetime,
        *,
        exclude_rss_feed_source_id: int | None = None,
        exclude_event_source_id: int | None = None,
    ) -> RegionEvent | None:
        """Return an existing RegionEvent that looks like a cross-source duplicate.

        Matches when:
        - Same region_calendar
        - start_date within DATE_WINDOW_DAYS
        - name similarity >= NAME_SIMILARITY_THRESHOLD
        - Comes from a *different* source than the one being excluded
        """
        from trips.models import RegionEvent

        start_date = start_datetime.date()
        window_start = start_date - timedelta(days=DATE_WINDOW_DAYS)
        window_end = start_date + timedelta(days=DATE_WINDOW_DAYS)

        candidates = RegionEvent.objects.filter(
            region_calendar=region_calendar,
            is_active=True,
            start_datetime__date__gte=window_start,
            start_datetime__date__lte=window_end,
        )

        # Exclude events from the same source so we only find cross-source matches.
        if exclude_rss_feed_source_id is not None:
            candidates = candidates.exclude(
                rss_feed_source_id=exclude_rss_feed_source_id
            )
        if exclude_event_source_id is not None:
            candidates = candidates.exclude(event_source_id=exclude_event_source_id)

        for candidate in candidates:
            if names_match(name, candidate.name) >= NAME_SIMILARITY_THRESHOLD:
                return candidate

        return None

    @staticmethod
    def find_same_source_near_duplicate(
        event_source: Any,
        *,
        name: str,
        start_datetime: datetime,
        location: str = "",
        description: str = "",
        meal_period: str | None = None,
        recurrence_pattern: str = "NONE",
        recurrence_days: str = "",
        category: str = "",
    ) -> RegionEvent | None:
        """Return an existing event from the same source that looks like a repost."""
        from trips.models import RegionEvent

        candidates = RegionEvent.objects.filter(
            event_source=event_source,
            is_active=True,
        )
        if category:
            candidates = candidates.filter(category=category)
        if meal_period:
            candidates = candidates.filter(meal_period=meal_period)

        if recurrence_pattern != "NONE":
            candidates = candidates.filter(
                recurrence_pattern=recurrence_pattern,
                recurrence_days=recurrence_days,
            )
        else:
            start_date = start_datetime.date()
            window_start = start_date - timedelta(days=DATE_WINDOW_DAYS)
            window_end = start_date + timedelta(days=DATE_WINDOW_DAYS)
            candidates = candidates.filter(
                recurrence_pattern="NONE",
                start_datetime__date__gte=window_start,
                start_datetime__date__lte=window_end,
            )

        for candidate in candidates:
            if _same_source_match(
                candidate,
                name=name,
                location=location,
                description=description,
            ):
                return candidate

        return None

    @staticmethod
    def find_same_venue_meal_merge_candidate(
        event_source: Any,
        *,
        name: str,
        start_datetime: datetime,
        location: str = "",
        category: str = "",
        meal_period: str | None = None,
    ) -> RegionEvent | None:
        """Find an existing event from the same venue on the same day with a
        different meal period, suitable for merging lunch+dinner into one card.

        Only activates for FOOD events with a meal_period and non-empty location.
        """
        from trips.models import RegionEvent

        if category.upper() != "FOOD" or not meal_period or not location:
            return None

        start_date = start_datetime.date()
        window_start = start_date - timedelta(days=DATE_WINDOW_DAYS)
        window_end = start_date + timedelta(days=DATE_WINDOW_DAYS)

        candidates = (
            RegionEvent.objects.filter(
                event_source=event_source,
                category="FOOD",
                is_active=True,
                start_datetime__date__gte=window_start,
                start_datetime__date__lte=window_end,
            )
            .exclude(
                meal_period=meal_period,
            )
            .exclude(
                meal_period__isnull=True,
            )
            .exclude(
                meal_period="",
            )
        )

        for candidate in candidates:
            if not candidate.location:
                continue
            location_score = text_similarity(location, candidate.location)
            if location_score < LOCATION_SIMILARITY_THRESHOLD:
                continue
            name_score = names_match(name, candidate.name)
            if name_score >= 0.6:
                return candidate

        return None

    @staticmethod
    def find_all_duplicates(
        region_calendar: RegionCalendar,
    ) -> list[tuple[RegionEvent, RegionEvent]]:
        """Find all cross-source duplicate pairs in a region calendar.

        Returns a list of (keep, remove) tuples. Prefers RSS-sourced events
        (rss_feed_source is not NULL) over scraper-sourced events.
        """
        from trips.models import RegionEvent

        events = list(
            RegionEvent.objects.filter(
                region_calendar=region_calendar,
                is_active=True,
            )
            .select_related("rss_feed_source", "event_source")
            .order_by("start_datetime", "name")
        )

        seen_ids: set[int] = set()
        pairs: list[tuple[RegionEvent, RegionEvent]] = []

        for i, event_a in enumerate(events):
            if event_a.pk in seen_ids:
                continue
            for event_b in events[i + 1 :]:
                if event_b.pk in seen_ids:
                    continue

                # Must be from different sources to be a cross-source dup.
                if not _are_different_sources(event_a, event_b):
                    continue

                date_diff = abs(
                    (event_a.start_datetime.date() - event_b.start_datetime.date()).days
                )
                if date_diff > DATE_WINDOW_DAYS:
                    continue

                if names_match(event_a.name, event_b.name) >= NAME_SIMILARITY_THRESHOLD:
                    keep, remove = _pick_keep_remove(event_a, event_b)
                    pairs.append((keep, remove))
                    seen_ids.add(remove.pk)

        return pairs


def _are_different_sources(a: RegionEvent, b: RegionEvent) -> bool:
    """Return True if two events come from different ingestion sources."""
    # One from RSS, one from scraper
    if a.rss_feed_source_id and not b.rss_feed_source_id:
        return True
    if b.rss_feed_source_id and not a.rss_feed_source_id:
        return True
    # Both from scraper but different EventSource
    if (
        a.event_source_id
        and b.event_source_id
        and a.event_source_id != b.event_source_id
        and not a.rss_feed_source_id
        and not b.rss_feed_source_id
    ):
        return True
    return False


def _pick_keep_remove(
    a: RegionEvent, b: RegionEvent
) -> tuple[RegionEvent, RegionEvent]:
    """Prefer RSS-sourced events. If tie, keep the older record (lower pk)."""
    a_is_rss = a.rss_feed_source_id is not None
    b_is_rss = b.rss_feed_source_id is not None

    if a_is_rss and not b_is_rss:
        return (a, b)
    if b_is_rss and not a_is_rss:
        return (b, a)

    # Same source type — keep whichever was created first.
    if a.created_at <= b.created_at:
        return (a, b)
    return (b, a)


def _same_source_match(
    candidate: RegionEvent,
    *,
    name: str,
    location: str,
    description: str,
) -> bool:
    name_score = names_match(name, candidate.name)
    description_score = text_similarity(description, candidate.description)
    has_location_evidence = bool(location and candidate.location)
    has_description_evidence = bool(description and candidate.description)

    # Same-source fuzzy dedupe is a safety net for reposted specials, not a
    # general merge rule. If we only have a short title and a nearby date,
    # the risk of collapsing distinct events is too high.
    if not has_location_evidence and not has_description_evidence:
        return False

    if has_location_evidence:
        location_score = text_similarity(location, candidate.location)
        if location_score < LOCATION_SIMILARITY_THRESHOLD:
            return False

    if name_score >= SAME_SOURCE_STRONG_NAME_SIMILARITY_THRESHOLD:
        return True
    if (
        name_score >= SAME_SOURCE_NAME_SIMILARITY_THRESHOLD
        and has_description_evidence
        and description_score >= DESCRIPTION_SIMILARITY_THRESHOLD
    ):
        return True
    if (
        has_description_evidence
        and description_score >= STRONG_DESCRIPTION_SIMILARITY_THRESHOLD
        and name_score >= 0.6
    ):
        return True
    return False

